// ----- 8< ----- FILE "./IMEM.v" ----- 8< -----

module IMEM #(
    ADDR_WIDTH = 64,
    INST_WIDTH = 32
) (
    input   [ADDR_WIDTH-1:0]    pc,
    output  [INST_WIDTH-1:0]    inst_data
    
);
    import "DPI-C" function int pimem_read(input longint unsigned paddr);
    assign inst_data = pimem_read(pc);
endmodule

// ----- 8< ----- FILE "./DMEM.v" ----- 8< -----

module DMEM #(
    ADDR_WIDTH = 64,
    DATA_WIDTH = 64,
    MASK_WIDTH = 8
) (
    input                       men,
    input                       mwen,
    input   [MASK_WIDTH-1:0]    wmask,
    input   [ADDR_WIDTH-1:0]    waddr,
    input   [ADDR_WIDTH-1:0]    raddr,
    input   [DATA_WIDTH-1:0]    wdata,
    output  [DATA_WIDTH-1:0]    rdata
);
    import "DPI-C" function longint unsigned pmem_read(input longint unsigned raddr);
    import "DPI-C" function void pmem_write(input longint unsigned waddr, input longint unsigned wdata, input byte unsigned wmask);

    reg [64-1:0] _rdata;
    always @(*) begin
        if (men) begin // 有读写请求时
            _rdata = pmem_read(raddr);
            if (mwen) begin // 有写请求时
                pmem_write(waddr, wdata, wmask);
            end
        end
        else begin
            _rdata = 0;
        end
    end
    assign rdata = _rdata;
endmodule

